WITH parsed AS (SELECT id, currency, tier_prices, discounts, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers WHERE currency = 'EUR') SELECT CASE WHEN entry_price >= 27 THEN 'LARGE' ELSE 'SMALL' END AS entry_price_tier, ROUND(SUM(lowest_price) / NULLIF(COUNT(CASE WHEN currency = 'EUR' THEN 1 END), 0), 2) AS lowest_price_per_eur, PERCENTILE_APPROX(lowest_price, 0.9) AS lowest_price_p90, COUNT(CASE WHEN currency = 'THB' THEN 1 END) AS thb_count FROM parsed GROUP BY CASE WHEN entry_price >= 27 THEN 'LARGE' ELSE 'SMALL' END;
